import{_ as a,o as i,c as t,a5 as r}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"Clarity Inclusion Types","description":"","frontmatter":{"title":"Clarity Inclusion Types","grading":"clarity-types"},"headers":[],"relativePath":"grading/clarity-types.md","filePath":"grading/clarity-types.md","lastUpdated":1790876393000}'),s={name:"grading/clarity-types.md"};function n(l,e,o,c,d,p){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="clarity-inclusion-types" tabindex="-1">Clarity Inclusion Types <a class="header-anchor" href="#clarity-inclusion-types" aria-label="Permalink to &quot;Clarity Inclusion Types&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The type, position, quantity, and visibility of inclusions and blemishes contribute to clarity descriptions. The same feature can matter differently across species and must be read with position, durability, and conditions.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-clarity-types-en"><p class="gem-identification-boundary__eyebrow">GRADING BOUNDARY</p><h2 id="identification-boundary-clarity-types-en">Boundary &amp; Safety</h2><p>This page explains clarity terms and observation dimensions; it does not infer value or durability from one inclusion name. Safety, transparency, and market interpretation depend on species, position, size, direction, and observation conditions. </p></aside><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Feather: fracture; durability impact depends on position, surface reach, direction, size, and species.</li><li>Cloud: hazy cluster; degrades transparency if dense.</li><li>Crystal / mineral: trapped inclusions (rutile, zircon, calcite).</li><li>Needle: rutile silk; gives sapphire its velvety look.</li><li>Blemish: surface chip / scratch / pit.</li><li>Location changes visibility, clarity interpretation, and durability risk; no single multiplier applies.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Grade</th><th>Note</th></tr></thead><tbody><tr><td>emerald</td><td>jardin (3-phase)</td><td>Species-specific inclusion description; read with transparency and durability</td></tr><tr><td>ruby</td><td>silk (rutile needles)</td><td>May relate to asterism; read with orientation, density, and cut</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page explains grading descriptions and report terms; the sources document the knowledge basis and do not make this page sufficient for grading, valuing, identifying, or determining the origin of a specific specimen.</p><ul><li><a href="https://www.gia.edu/diamond-quality-factor" target="_blank" rel="noreferrer">GIA: Diamond Quality Factors</a><span>Diamond quality factors including color, clarity, cut, and carat weight; not a price formula</span><small>Open source ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-clarity/" target="_blank" rel="noreferrer">GIA 4Cs: Diamond Clarity</a><span>Introductory explanation of FL–I3 clarity grades and the 10× observation condition</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA: Colored Gemstone Value Factors</a><span>Colour, cut, clarity, durability, and market factors vary by gemstone species</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/UK-EN/emerald-quality-factor" target="_blank" rel="noreferrer">GIA: Emerald Quality Factors</a><span>Species-specific context for emerald colour, transparency, inclusions, and treatment</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA: Analytical Methods Used in Geographic Origin Determination</a><span>Origin opinions use multiple evidence types and may remain inconclusive</span><small>Open source ↗</small></li><li><a href="https://www.ftc.gov/news-events/topics/tools-consumers/jewelry-guides" target="_blank" rel="noreferrer">FTC: Jewelry, Precious Metals, and Pewter Industries Guides</a><span>US consumer and marketing disclosure guidance; not automatically the law of every jurisdiction</span><small>Open source ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-clarity-types-en"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-clarity-types-en">Evidence map for this page</h2><p class="gem-reference-block__intro">Claims are mapped to references and labelled with their evidence status in this knowledge base.</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">Source-supported</strong><span>The same inclusion can mean different things across species and must be assessed with position, visibility, durability, and observation conditions.</span><small>GIA 4Cs: Diamond Clarity; GIA: Emerald Quality Factors</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">Teaching summary</strong><span>A feather may affect durability depending on position, surface reach, direction, size, and species; its name alone is insufficient.</span><small>GIA 4Cs: Diamond Clarity; GIA: Emerald Quality Factors</small></li></ul></aside><p><em>See the <a href="./intro.html">grading overview</a>.</em></p>',11)])])}const y=a(s,[["render",n]]);export{m as __pageData,y as default};
